export default CoreValues

'use client';

import type { MemeAssetType } from '../types';

const STATUS_CONFIG: Record<string, { label: string; color: string; bg: string }> = {
  uploaded:  { label: 'Uploaded',  color: 'text-blue-600',  bg: 'bg-blue-50' },
  analyzing: { label: 'Analyzing', color: 'text-purple-600', bg: 'bg-purple-50' },
  analyzed:  { label: 'Analyzed',  color: 'text-green-600', bg: 'bg-green-50' },
  approved:  { label: 'Approved',  color: 'text-emerald-600', bg: 'bg-emerald-50' },
  rejected:  { label: 'Rejected',  color: 'text-red-600',   bg: 'bg-red-50' },
  published: { label: 'Published', color: 'text-slate-600', bg: 'bg-slate-100' },
};

interface Props {
  item: MemeAssetType;
  selected: boolean;
  onSelect: (id: string) => void;
  onAnalyze: (id: string) => void;
  onDelete: (id: string) => void;
}

function formatBytes(bytes: number) {
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

export default function AdminQueueCard({ item, selected, onSelect, onAnalyze, onDelete }: Props) {
  const id = item._id ?? '';
  const status = STATUS_CONFIG[item.reviewStatus] ?? STATUS_CONFIG.uploaded;
  const isAnalyzing = item.reviewStatus === 'analyzing';

  return (
    <div
      className={`bg-surface-container-lowest p-4 rounded-2xl shadow-sm border transition-all flex gap-4 items-start group
        ${selected ? 'border-primary/40 shadow-primary/10' : 'border-slate-50'}`}
    >
      {/* Thumbnail */}
      <div className="relative w-24 h-24 rounded-xl overflow-hidden bg-slate-100 flex-shrink-0">
        {item.thumbnailUrl ? (
          <img src={item.thumbnailUrl} alt={item.title} className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full flex items-center justify-center bg-slate-200">
            <span className="material-symbols-outlined text-slate-400 text-3xl">videocam</span>
          </div>
        )}
        {isAnalyzing && (
          <div className="absolute inset-0 bg-black/30 flex items-center justify-center">
            <span className="material-symbols-outlined text-white animate-spin">sync</span>
          </div>
        )}
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <div className="flex justify-between items-start mb-1">
          <div className="flex items-center gap-2 min-w-0">
            <input
              type="checkbox"
              checked={selected}
              onChange={() => onSelect(id)}
              onClick={(e) => e.stopPropagation()}
              className="w-4 h-4 rounded border-slate-300 text-primary focus:ring-primary flex-shrink-0"
            />
            <h4 className="font-bold text-sm truncate">{item.originalFileName}</h4>
          </div>
          <button
            onClick={(e) => { e.stopPropagation(); onDelete(id); }}
            className="text-outline hover:text-error transition-colors flex-shrink-0 ml-2"
            title="Delete"
          >
            <span className="material-symbols-outlined text-[18px]">delete</span>
          </button>
        </div>

        <p className="text-xs text-outline mb-3">
          {formatBytes(item.sizeBytes)}{item.duration ? ` ΓÇó ${item.duration}` : ''}
        </p>

        {/* Progress bar */}
        <div className="flex items-center gap-2 mb-2">
          <div className="flex-1 h-1.5 bg-slate-100 rounded-full overflow-hidden">
            <div
              className={`h-full rounded-full transition-all ${
                item.reviewStatus === 'uploaded' ? 'bg-blue-400 w-full' :
                isAnalyzing ? 'bg-purple-400 w-2/3 animate-pulse' :
                item.reviewStatus === 'analyzed' ? 'bg-green-400 w-full' :
                'bg-primary w-full'
              }`}
            />
          </div>
          <span className={`text-[10px] font-bold ${status.color}`}>
            {isAnalyzing ? 'ΓÇª' : 'DONE'}
          </span>
        </div>

        <div className="flex items-center justify-between">
          <span className={`inline-block px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${status.bg} ${status.color}`}>
            {status.label}
          </span>
          {item.reviewStatus === 'uploaded' && (
            <button
              onClick={() => onAnalyze(id)}
              className="text-[10px] font-bold text-primary hover:underline flex items-center gap-1"
            >
              <span className="material-symbols-outlined text-sm">auto_awesome</span> Analyze
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import type { MemeAssetType } from '../types';

const CATEGORIES = [
  'Reaction', 'Shock', 'Celebration', 'Working', 'Cinematic',
  'Funny', 'Sad', 'Gaming', 'Confused', 'Intro', 'Outro',
  'Meme Pack', 'Random', 'Animals', 'Career',
];

interface Props {
  item: MemeAssetType;
  onApprove: (id: string, fields: {
    title: string; category: string; tags: string[];
    description: string; trending: boolean; featured: boolean;
  }) => void;
  onReject: (id: string) => void;
  onReanalyze: (id: string) => void;
}

export default function AdminReviewCard({ item, onApprove, onReject, onReanalyze }: Props) {
  const id = item._id ?? '';
  const ai = item.aiSuggestion;

  const [title, setTitle]       = useState(ai?.title       ?? item.title);
  const [category, setCategory] = useState(ai?.category    ?? item.category ?? 'Reaction');
  const [description, setDesc]  = useState(ai?.description ?? item.description ?? '');
  const [tags, setTags]         = useState<string[]>(ai?.tags ?? item.tags ?? []);
  const [newTag, setNewTag]     = useState('');
  const [trending, setTrending] = useState(false);
  const [featured, setFeatured] = useState(false);

  const confidence = ai?.confidence ?? 0;

  function addTag() {
    const t = newTag.trim().replace(/^#/, '');
    if (t && !tags.includes(`#${t}`)) setTags([...tags, `#${t}`]);
    setNewTag('');
  }

  function removeTag(tag: string) {
    setTags(tags.filter((t) => t !== tag));
  }

  return (
    <div className="bg-surface-container-lowest rounded-2xl shadow-sm border border-slate-50 overflow-hidden flex flex-col md:flex-row">
      {/* Thumbnail */}
      <div className="md:w-72 relative flex-shrink-0 group min-h-[200px] bg-slate-100">
        {item.thumbnailUrl ? (
          <img src={item.thumbnailUrl} alt={item.title} className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full min-h-[200px] flex flex-col items-center justify-center gap-2 text-slate-400 bg-slate-100">
            <span className="material-symbols-outlined text-5xl">videocam</span>
            <span className="text-xs font-bold">{item.originalFileName}</span>
          </div>
        )}
        {/* Confidence badge */}
        {confidence > 0 && (
          <div className="absolute top-3 left-3 px-3 py-1 rounded-full bg-black/60 backdrop-blur-sm text-white text-[10px] font-bold flex items-center gap-1">
            <span className="material-symbols-outlined text-xs text-green-400" style={{ fontVariationSettings: "'FILL' 1" }}>verified</span>
            {Math.round(confidence * 100)}% AI Confidence
          </div>
        )}
      </div>

      {/* Fields */}
      <div className="flex-1 p-6 space-y-4">
        <div className="grid grid-cols-2 gap-4">
          {/* Title */}
          <div className="col-span-2">
            <label className="text-[10px] font-extrabold text-outline uppercase tracking-wider mb-1 block">Title</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-surface-container-low border-none rounded-xl text-sm font-semibold focus:ring-primary px-3 py-2.5 outline-none"
            />
          </div>

          {/* Category */}
          <div>
            <label className="text-[10px] font-extrabold text-outline uppercase tracking-wider mb-1 block">Category</label>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="w-full bg-surface-container-low border-none rounded-xl text-sm font-semibold focus:ring-primary px-3 py-2.5"
            >
              {CATEGORIES.map((c) => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>
          </div>

          {/* Original file */}
          <div>
            <label className="text-[10px] font-extrabold text-outline uppercase tracking-wider mb-1 block">Original File</label>
            <div className="text-xs text-outline py-3 px-1 truncate">{item.originalFileName}</div>
          </div>

          {/* Description */}
          <div className="col-span-2">
            <label className="text-[10px] font-extrabold text-outline uppercase tracking-wider mb-1 block">Description</label>
            <textarea
              rows={2}
              value={description}
              onChange={(e) => setDesc(e.target.value)}
              className="w-full bg-surface-container-low border-none rounded-xl text-sm focus:ring-primary px-3 py-2.5 resize-none outline-none"
            />
          </div>

          {/* Toggles */}
          <div className="col-span-2 flex items-center gap-6">
            <label className="flex items-center gap-2 text-sm font-semibold cursor-pointer">
              <input type="checkbox" checked={trending} onChange={(e) => setTrending(e.target.checked)}
                className="w-4 h-4 rounded border-slate-300 text-primary focus:ring-primary" />
              Trending
            </label>
            <label className="flex items-center gap-2 text-sm font-semibold cursor-pointer">
              <input type="checkbox" checked={featured} onChange={(e) => setFeatured(e.target.checked)}
                className="w-4 h-4 rounded border-slate-300 text-primary focus:ring-primary" />
              Featured
            </label>
          </div>
        </div>

        {/* Tags */}
        <div>
          <label className="text-[10px] font-extrabold text-outline uppercase tracking-wider mb-2 block">Suggested Tags</label>
          <div className="flex flex-wrap gap-2">
            {tags.map((tag) => (
              <span
                key={tag}
                className="px-3 py-1 rounded-full bg-primary/10 text-primary text-xs font-bold flex items-center gap-1"
              >
                {tag}
                <button onClick={() => removeTag(tag)} className="hover:text-error transition-colors">
                  <span className="material-symbols-outlined text-[14px]">close</span>
                </button>
              </span>
            ))}
            <div className="flex items-center gap-1">
              <input
                value={newTag}
                onChange={(e) => setNewTag(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addTag()}
                placeholder="add tag"
                className="w-20 text-xs bg-slate-100 border-none rounded-full px-2 py-1 outline-none focus:ring-1 focus:ring-primary"
              />
              <button
                onClick={addTag}
                className="w-6 h-6 rounded-full bg-slate-100 text-slate-400 flex items-center justify-center hover:bg-primary/20 hover:text-primary transition-colors"
              >
                <span className="material-symbols-outlined text-sm">add</span>
              </button>
            </div>
          </div>
        </div>

        {/* Action buttons */}
        <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-50">
          <button
            onClick={() => onReject(id)}
            className="text-error text-xs font-bold px-4 py-2 hover:bg-error/5 rounded-lg transition-colors"
          >
            Reject
          </button>
          <button
            onClick={() => onReanalyze(id)}
            className="text-on-secondary-fixed-variant text-xs font-bold px-4 py-2 bg-secondary-container rounded-lg hover:opacity-80 transition-opacity"
          >
            Re-analyze
          </button>
          <button
            onClick={() => onApprove(id, { title, category, tags, description, trending, featured })}
            className="bg-primary text-white text-xs font-bold px-6 py-2 rounded-lg shadow-sm hover:scale-105 transition-all"
          >
            Save &amp; Approve
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useRef } from 'react';
import type { MemeAssetType } from '../types';
import { generateVideoThumbnail } from '@/lib/video';

interface Props {
  onSyncComplete: () => void;
  onAnalyze?: (id: string, frameData?: string) => Promise<void>;
}

export default function AdminSyncSection({ onSyncComplete, onAnalyze }: Props) {
  const [loading, setLoading] = useState(false);
  const [unsynced, setUnsynced] = useState<any[]>([]);
  const [processing, setProcessing] = useState<string | null>(null);
  const [show, setShow] = useState(false);

  async function fetchUnsynced() {
    setLoading(true);
    try {
      const res = await fetch('/api/admin/memes/sync');
      const data = await res.json();
      setUnsynced(data.items || []);
      setShow(true);
    } catch (err) {
      console.error('Failed to fetch unsynced', err);
    } finally {
      setLoading(false);
    }
  }

  async function processItem(item: any) {
    setProcessing(item.key);
    try {
      // 1. Generate thumbnail from R2 URL (browser side)
      // Note: This requires CORS enabled on the R2 bucket
      const videoRes = await fetch(item.publicUrl);
      const blob = await videoRes.blob();
      const file = new File([blob], item.filename, { type: 'video/mp4' });

      let thumbnailBlob: Blob | null = null;
      try {
        thumbnailBlob = await generateVideoThumbnail(file);
      } catch (err) {
        console.error('Thumbnail generation failed for sync', err);
      }

      // 2. Upload thumbnail if generated
      let thumbnailUrl = '';
      if (thumbnailBlob) {
        const thumbPresignedRes = await fetch('/api/admin/memes/upload/presigned', {
          method: 'POST',
          body: JSON.stringify({ filename: 'thumbnail.jpg', contentType: 'image/jpeg', folder: 'thumbnails' })
        });
        const thumbData = await thumbPresignedRes.json();
        if (thumbPresignedRes.ok) {
          await fetch(thumbData.uploadUrl, { method: 'PUT', body: thumbnailBlob, headers: { 'Content-Type': 'image/jpeg' } });
          thumbnailUrl = thumbData.publicUrl;
        }
      }

      // 3. Complete sync (save to MongoDB)
      const completeRes = await fetch('/api/admin/memes/upload/complete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: item.filename.replace(/\.[^/.]+$/, '').replace(/[-_]/g, ' '),
          originalFileName: item.filename,
          slug: `${item.filename.replace(/\.[^/.]+$/, '')}-${Date.now()}`,
          storageKey: item.key,
          publicUrl: item.publicUrl,
          mimeType: 'video/mp4',
          sizeBytes: item.size,
          thumbnailUrl: thumbnailUrl,
        })
      });

      const completeData = await completeRes.json();
      if (completeRes.ok && completeData.item?._id) {
        setUnsynced((prev) => prev.filter((i) => i.key !== item.key));

        // 4. Trigger AI analysis with the thumbnail frame if onAnalyze is provided
        if (onAnalyze && thumbnailBlob) {
          const reader = new FileReader();
          reader.readAsDataURL(thumbnailBlob);
          reader.onloadend = async () => {
            const base64data = reader.result as string;
            await onAnalyze(completeData.item._id, base64data);
          };
        } else if (onAnalyze) {
          await onAnalyze(completeData.item._id);
        }
      }
    } catch (err) {
      console.error('Processing failed', err);
    } finally {
      setProcessing(null);
    }
  }

  async function processAll() {
    for (const item of unsynced) {
      await processItem(item);
    }
    onSyncComplete();
  }

  if (!show) {
    return (
      <div className="bg-surface-container-low rounded-2xl p-6 mb-8 border border-slate-100 flex items-center justify-between">
        <div>
          <h4 className="font-bold text-lg mb-1 font-headline">R2 Bucket Sync</h4>
          <p className="text-sm text-outline">Detect and import files uploaded directly to Cloudflare R2.</p>
        </div>
        <button
          onClick={fetchUnsynced}
          disabled={loading}
          className="bg-secondary text-on-secondary px-6 py-2 rounded-xl font-bold flex items-center gap-2 hover:opacity-90 transition-all disabled:opacity-50"
        >
          {loading ? (
            <span className="material-symbols-outlined animate-spin text-sm">sync</span>
          ) : (
            <span className="material-symbols-outlined text-sm">find_in_page</span>
          )}
          Check for new files
        </button>
      </div>
    );
  }

  return (
    <div className="bg-surface-container-low rounded-2xl p-8 mb-8 border border-slate-100 animate-in fade-in slide-in-from-top-4">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h4 className="font-extrabold text-2xl font-headline flex items-center gap-2 text-on-surface">
            <span className="material-symbols-outlined text-primary">cloud_sync</span>
            Unsynced Assets ({unsynced.length})
          </h4>
          <p className="text-sm text-outline font-medium mt-1">Found in R2 /memes folder but missing from library.</p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setShow(false)}
            className="text-sm font-bold text-outline hover:text-on-surface transition-colors"
          >
            Collapse
          </button>
          <button
            onClick={processAll}
            disabled={!unsynced.length || !!processing}
            className="bg-primary text-on-primary px-6 py-2 rounded-xl font-bold shadow-lg shadow-primary/20 hover:scale-105 transition-all disabled:opacity-50 disabled:scale-100"
          >
            Process All
          </button>
        </div>
      </div>

      {unsynced.length === 0 ? (
        <div className="py-8 text-center text-outline font-bold bg-surface-container-lowest rounded-xl border border-dashed border-slate-200">
          Bucket is in sync. Everything is accounted for!
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {unsynced.map((item) => (
            <div key={item.key} className="bg-surface-container-lowest p-4 rounded-xl border border-slate-100 flex items-center justify-between shadow-sm">
              <div className="flex-1 min-w-0">
                <p className="font-bold text-sm truncate pr-4 text-on-surface">{item.filename}</p>
                <p className="text-[10px] text-outline mt-1 font-mono uppercase">
                  {(item.size / 1024 / 1024).toFixed(1)} MB ΓÇó {item.key}
                </p>
              </div>
              <button
                onClick={() => processItem(item)}
                disabled={!!processing}
                className={`p-2 rounded-lg transition-all ${
                  processing === item.key 
                  ? 'bg-slate-100 text-slate-400' 
                  : 'bg-primary-container text-on-primary-container hover:bg-primary hover:text-on-primary'
                }`}
              >
                {processing === item.key ? (
                  <span className="material-symbols-outlined text-sm animate-spin">sync</span>
                ) : (
                  <span className="material-symbols-outlined text-sm">add</span>
                )}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import { useCallback, useEffect, useState } from 'react';
import type { MemeAssetType, PipelineStats } from './types';
import AdminSidebar from './components/AdminSidebar';
import AdminHeader from './components/AdminHeader';
import AdminUploadDropzone from './components/AdminUploadDropzone';
import AdminQueueCard from './components/AdminQueueCard';
import AdminReviewCard from './components/AdminReviewCard';
import AdminStatsSidebar from './components/AdminStatsSidebar';
import AdminSyncSection from './components/AdminSyncSection';
import { generateVideoThumbnail } from '@/lib/video';

/* ------------------------------------------------------------------ */
/* Helpers                                                              */
/* ------------------------------------------------------------------ */
function derivePipelineStats(items: MemeAssetType[]): PipelineStats {
  return {
    uploaded:  items.filter((i) => i.reviewStatus === 'uploaded').length,
    analyzed:  items.filter((i) => i.reviewStatus === 'analyzed').length,
    pending:   items.filter((i) => ['uploaded', 'analyzing', 'analyzed'].includes(i.reviewStatus)).length,
    published: items.filter((i) => i.reviewStatus === 'published').length,
    failed:    items.filter((i) => i.reviewStatus === 'rejected').length,
  };
}

/* ------------------------------------------------------------------ */
/* Page                                                                 */
/* ------------------------------------------------------------------ */
export default function AdminMemesPage() {
  const [items, setItems]           = useState<MemeAssetType[]>([]);
  const [selected, setSelected]     = useState<Set<string>>(new Set());
  const [uploading, setUploading]   = useState(false);
  const [statusFilter, setStatusFilter] = useState('all');
  const [searchQ, setSearchQ]       = useState('');
  const [toast, setToast]           = useState('');

  /* ---- Data loading ---- */
  const loadPending = useCallback(async () => {
    const res  = await fetch('/api/admin/memes/pending');
    const data = await res.json();
    setItems(data.items ?? []);
  }, []);

  useEffect(() => { loadPending(); }, [loadPending]);

  function showToast(msg: string) {
    setToast(msg);
    setTimeout(() => setToast(''), 3000);
  }

  /* ---- Upload (Direct to R2) ---- */
  async function handleUpload(files: File[]) {
    setUploading(true);
    const batch = files.slice(0, 10);
    
    for (const file of batch) {
      try {
        showToast(`Preparing upload for ${file.name}...`);
        
        // 1. Generate thumbnail locally
        let thumbnailBlob: Blob | null = null;
        if (file.type.startsWith('video/')) {
          try {
            thumbnailBlob = await generateVideoThumbnail(file);
          } catch (err) {
            console.error('Thumbnail gen failed', err);
          }
        }

        // 2. Get presigned URL for the video/asset
        const assetRes = await fetch('/api/admin/memes/upload/presigned', {
          method: 'POST',
          body: JSON.stringify({ filename: file.name, contentType: file.type || 'video/mp4' })
        });
        const assetData = await assetRes.json();
        if (!assetRes.ok) throw new Error('Failed to get asset presigned URL');

        // 3. Upload video direct to R2
        await fetch(assetData.uploadUrl, {
          method: 'PUT',
          body: file,
          headers: { 'Content-Type': file.type || 'video/mp4' }
        });

        // 4. Upload thumbnail if exists
        let finalThumbnailUrl = '';
        if (thumbnailBlob) {
          const thumbPresignedRes = await fetch('/api/admin/memes/upload/presigned', {
            method: 'POST',
            body: JSON.stringify({ filename: 'thumbnail.jpg', contentType: 'image/jpeg', folder: 'thumbnails' })
          });
          const thumbPresignedData = await thumbPresignedRes.json();
          if (thumbPresignedRes.ok) {
            await fetch(thumbPresignedData.uploadUrl, {
              method: 'PUT',
              body: thumbnailBlob,
              headers: { 'Content-Type': 'image/jpeg' }
            });
            finalThumbnailUrl = thumbPresignedData.publicUrl;
          }
        }

        // 5. Tell backend to save the metadata
        try {
          await fetch('/api/admin/memes/upload/complete', {
            method: 'POST',
            body: JSON.stringify({
              title: assetData.rawTitle.replace(/[-_]/g, ' '),
              originalFileName: file.name,
              slug: assetData.slug,
              storageKey: assetData.key,
              publicUrl: assetData.publicUrl,
              mimeType: file.type || 'video/mp4',
              sizeBytes: file.size,
              thumbnailUrl: finalThumbnailUrl,
            })
          });
        } catch (saveErr) {
          console.error('Metadata save failed, but file is in R2', saveErr);
        }

      } catch (err) {
        console.error('Upload flow failed for', file.name, err);
        showToast(`Failed to upload ${file.name}`);
      }
    }

    await loadPending();
    showToast(`Upload batch complete Γ£ô`);
    setUploading(false);
  }

  /* ---- Analyze (single or batch) ---- */
  async function analyzeIds(ids: string[]) {
    if (!ids.length) return;
    showToast(`Analyzing ${ids.length} item(s)ΓÇª`);
    // Optimistic UI: mark as analyzing
    setItems((prev) =>
      prev.map((it) => ids.includes(it._id ?? '') ? { ...it, reviewStatus: 'analyzing' } : it)
    );
    const res = await fetch('/api/admin/memes/analyze', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ids }),
    });
    if (res.ok) { await loadPending(); showToast('Analysis complete Γ£ô'); }
    else        { showToast('Analysis failed.'); await loadPending(); }
  }

  /* ---- Approve single ---- */
  async function handleApprove(id: string, fields: {
    title: string; category: string; tags: string[];
    description: string; trending: boolean; featured: boolean;
  }) {
    const res = await fetch('/api/admin/memes/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        items: [{ id, ...fields, visibility: 'public' }],
      }),
    });
    if (res.ok) { await loadPending(); showToast(`"${fields.title}" published Γ£ô`); }
    else        { showToast('Save failed.'); }
  }

  /* ---- Reject single ---- */
  async function handleReject(id: string) {
    await fetch(`/api/admin/memes/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ reviewStatus: 'rejected' }),
    });
    await loadPending();
    showToast('Rejected.');
  }

  /* ---- Delete single ---- */
  async function handleDelete(id: string) {
    await fetch(`/api/admin/memes/${id}`, { method: 'DELETE' });
    setItems((prev) => prev.filter((it) => it._id !== id));
    setSelected((prev) => { const s = new Set(prev); s.delete(id); return s; });
    showToast('Deleted.');
  }

  /* ---- Re-analyze ---- */
  async function handleReanalyze(id: string) { await analyzeIds([id]); }

  /* ---- Batch publish ---- */
  async function handleBatchPublish() {
    const analyzed = items.filter((it) => it.reviewStatus === 'analyzed').map((it) => ({
      id:          it._id ?? '',
      title:       it.aiSuggestion?.title    ?? it.title,
      category:    it.aiSuggestion?.category ?? it.category ?? 'Random',
      tags:        it.aiSuggestion?.tags     ?? it.tags ?? [],
      description: it.aiSuggestion?.description ?? '',
      trending:    false,
      featured:    false,
      visibility:  'public' as const,
    }));
    if (!analyzed.length) { showToast('No analyzed items to publish.'); return; }
    const res = await fetch('/api/admin/memes/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: analyzed }),
    });
    if (res.ok) { await loadPending(); showToast(`${analyzed.length} item(s) published Γ£ô`); }
    else        { showToast('Batch publish failed.'); }
  }

  /* ---- Select helpers ---- */
  function toggleSelect(id: string) {
    setSelected((prev) => {
      const s = new Set(prev);
      s.has(id) ? s.delete(id) : s.add(id);
      return s;
    });
  }
  function toggleSelectAll() {
    if (selected.size === filteredItems.length) { setSelected(new Set()); }
    else                                        { setSelected(new Set(filteredItems.map((it) => it._id ?? ''))); }
  }

  /* ---- Filtered view ---- */
  const filteredItems = items.filter((it) => {
    const matchStatus = statusFilter === 'all' || it.reviewStatus === statusFilter;
    const matchQ      = !searchQ || it.title.toLowerCase().includes(searchQ.toLowerCase()) ||
                        it.originalFileName.toLowerCase().includes(searchQ.toLowerCase());
    return matchStatus && matchQ;
  });

  const reviewableItems = filteredItems.filter((it) => it.reviewStatus === 'analyzed');
  const queueItems      = filteredItems.filter((it) => it.reviewStatus !== 'analyzed' && it.reviewStatus !== 'published' && it.reviewStatus !== 'rejected');

  const stats = derivePipelineStats(items);

  /* ------------------------------------------------------------------ */
  return (
    <div className="flex min-h-screen bg-background text-on-surface">
      <AdminSidebar />

      <div className="ml-64 flex flex-col flex-1">
        <AdminHeader onSearch={setSearchQ} />

        <main className="flex-1 p-8">
          {/* Page Header */}
          <section className="mb-10 flex flex-col lg:flex-row lg:items-end justify-between gap-6">
            <div>
              <h2 className="text-3xl font-extrabold tracking-tight text-on-surface mb-2 font-headline">
                Meme Upload Manager
              </h2>
              <p className="text-outline font-medium">
                Streamline your content pipeline with automated AI metadata generation.
              </p>
              <div className="flex flex-wrap gap-3 mt-6">
                {[
                  { color: 'bg-primary',    label: `${stats.uploaded} Uploaded` },
                  { color: 'bg-tertiary',   label: `${stats.analyzed} Analyzed` },
                  { color: 'bg-yellow-500', label: `${stats.pending} Pending` },
                  { color: 'bg-green-500',  label: `${stats.published} Published` },
                ].map((s) => (
                  <div key={s.label} className="bg-surface-container-lowest px-4 py-2 rounded-xl flex items-center gap-3 shadow-sm border border-slate-50">
                    <span className={`w-2 h-2 rounded-full ${s.color}`}></span>
                    <span className="text-sm font-semibold">{s.label}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button
                onClick={() => analyzeIds([...selected].filter((id) =>
                  items.find((it) => it._id === id)?.reviewStatus === 'uploaded'
                ))}
                className="bg-surface-container-highest text-on-secondary-container px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-300 transition-all"
              >
                <span className="material-symbols-outlined">psychology</span>
                Analyze with AI
              </button>
              <button
                onClick={handleBatchPublish}
                className="bg-primary text-on-primary px-8 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-105 transition-all"
              >
                <span className="material-symbols-outlined">publish</span>
                Save Approved
              </button>
            </div>
          </section>

          <div className="grid grid-cols-12 gap-8">
            {/* Left column */}
            <div className="col-span-12 lg:col-span-8 space-y-8">
              {/* Sync Section */}
              <AdminSyncSection 
                onSyncComplete={loadPending} 
                onAnalyze={async (id, frameData) => {
                  showToast(`Analyzing synced itemΓÇª`);
                  const res = await fetch('/api/admin/memes/analyze', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ ids: [id], frameData }),
                  });
                  if (res.ok) { await loadPending(); showToast('Analysis complete Γ£ô'); }
                }}
              />

              {/* Dropzone */}
              <AdminUploadDropzone onFilesSelected={handleUpload} uploading={uploading} />

              {/* Batch Toolbar */}
              <div className="sticky top-20 z-30 bg-surface-container-lowest/80 backdrop-blur-md px-6 py-4 rounded-2xl shadow-sm border border-slate-50 flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <input
                    type="checkbox"
                    className="w-5 h-5 rounded border-slate-300 text-primary focus:ring-primary"
                    checked={selected.size > 0 && selected.size === filteredItems.length}
                    onChange={toggleSelectAll}
                  />
                  <span className="text-sm font-bold">
                    {selected.size > 0 ? `${selected.size} selected` : 'Select All'}
                  </span>
                  <div className="h-6 w-px bg-slate-200 mx-2"></div>
                  <button
                    className="text-sm font-bold text-primary flex items-center gap-1 hover:underline"
                    onClick={() => analyzeIds([...selected])}
                  >
                    <span className="material-symbols-outlined text-lg">auto_awesome</span>
                    Analyze
                  </button>
                  <button
                    className="text-sm font-bold text-error flex items-center gap-1 hover:underline"
                    onClick={async () => {
                      for (const id of selected) await handleDelete(id);
                      setSelected(new Set());
                    }}
                  >
                    <span className="material-symbols-outlined text-lg">delete</span>
                    Delete
                  </button>
                </div>
                <div className="flex items-center gap-3">
                  <select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    className="bg-surface-container-low border-none rounded-lg text-xs font-bold px-3 py-2 focus:ring-1 focus:ring-primary"
                  >
                    <option value="all">All Status</option>
                    <option value="uploaded">Uploaded</option>
                    <option value="analyzing">Analyzing</option>
                    <option value="analyzed">Analyzed</option>
                    <option value="rejected">Rejected</option>
                  </select>
                </div>
              </div>

              {/* Queue Grid */}
              {queueItems.length > 0 && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {queueItems.map((item) => (
                    <AdminQueueCard
                      key={item._id}
                      item={item}
                      selected={selected.has(item._id ?? '')}
                      onSelect={toggleSelect}
                      onAnalyze={(id) => analyzeIds([id])}
                      onDelete={handleDelete}
                    />
                  ))}
                </div>
              )}

              {/* AI Review Section */}
              {reviewableItems.length > 0 && (
                <div className="space-y-6">
                  <h3 className="text-xl font-bold flex items-center gap-2 font-headline">
                    <span className="material-symbols-outlined text-tertiary">auto_fix_high</span>
                    Review AI Suggestions ({reviewableItems.length})
                  </h3>
                  {reviewableItems.map((item) => (
                    <AdminReviewCard
                      key={item._id}
                      item={item}
                      onApprove={handleApprove}
                      onReject={handleReject}
                      onReanalyze={handleReanalyze}
                    />
                  ))}
                </div>
              )}

              {/* Empty state */}
              {queueItems.length === 0 && reviewableItems.length === 0 && (
                <div className="bg-surface-container-lowest rounded-2xl p-12 text-center border border-dashed border-slate-200 shadow-sm">
                  <span className="material-symbols-outlined text-5xl text-outline mb-4 block">inbox</span>
                  <p className="font-bold text-on-surface-variant">No items in the queue.</p>
                  <p className="text-sm text-outline mt-1">Upload videos above to get started.</p>
                </div>
              )}
            </div>

            {/* Right column */}
            <AdminStatsSidebar stats={stats} />
          </div>
        </main>
      </div>

      {/* Toast */}
      {toast && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[200] bg-slate-900 text-white px-6 py-3 rounded-full shadow-2xl text-sm font-bold animate-bounce-in">
          {toast}
        </div>
      )}
    </div>
  );
}

