// lib/articles
// Fetch all articles with pagination support
export async function getAllArticles(
  page: number = 1,
  limit: number = 6,
  category?: string
): Promise<{
  articles: Article[];
  total: number;
  totalPages: number;
}> {
  const start = (page - 1) * limit;
  const end = start + limit;

  // Build the query based on category filter
  let query = `*[_type == "article"`;

  if (category && category !== "all") {
    query += ` && category == "${category}"`;
  }

  query += `] | order(publishedAt desc) [${start}...${end}] {
    _id,
    title,
    "slug": slug.current,
    description,
    excerpt,
    category,
    publishedAt,
    readTime,
    author->{
      name,
      "title": role,
      "avatar": avatar.asset->url
    },
    "image": image.asset->url,
    badgeColor,
    tags[]->{
      name,
      badgeColor
    }
  }`;

  const countQuery = `count(*[_type == "article" ${
    category && category !== "all" ? `&& category == "${category}"` : ""
  }])`;

  try {
    const [articles, total] = await Promise.all([
      client.fetch(query),
      client.fetch(countQuery),
    ]);

    // Transform Sanity data to match your Article interface
    const transformedArticles: Article[] = articles.map((article: any) => ({
      id: article._id,
      title: article.title,
      slug: article.slug,
      description: article.description || "",
      excerpt:
        article.excerpt || article.description?.substring(0, 150) + "...",
      category: article.category,
      readTime: article.readTime || "5 min read",
      date: new Date(article.publishedAt).toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric",
      }),
      image: article.image || "/default-article.jpg",
      badgeColor: article.badgeColor || "#330df2",
      author: {
        name: article.author?.name || "Unknown Author",
        title: article.author?.title || "",
        avatar: article.author?.avatar || "/default-avatar.jpg",
      },
      tags: (article.tags || []).map((tag: any) => ({
        name: tag.name,
        color: tag.badgeColor,
      })),
    }));

    return {
      articles: transformedArticles,
      total,
      totalPages: Math.ceil(total / limit),
    };
  } catch (error) {
    console.error("Error fetching articles:", error);
    return {
      articles: [],
      total: 0,
      totalPages: 0,
    };
  }
}

// Fetch a single article by slug
export async function getArticleBySlug(slug: string): Promise<Article | null> {
  const query = `*[_type == "article" && slug.current == $slug][0] {
    _id,
    title,
    "slug": slug.current,
    description,
    excerpt,
    category,
    publishedAt,
    readTime,
    author->{
      name,
      "title": role,
      "avatar": avatar.asset->url,
      bio
    },
    "image": image.asset->url,
    badgeColor,
    body[]{
      ...,
      _type == "image" => {
        ...,
        asset->
      },
      markDefs[]{
        ...,
        _type == "link" => {
          ...,
          "href": @.href
        }
      }
    },
    tags[]->{
      name,
      badgeColor
    }
  }`;

  try {
    const article = await client.fetch(query, { slug });

    if (!article) return null;

    return {
      id: article._id,
      title: article.title,
      slug: article.slug,
      description: article.description || "",
      excerpt:
        article.excerpt || article.description?.substring(0, 150) + "...",
      category: article.category,
      readTime: article.readTime || "5 min read",
      date: new Date(article.publishedAt).toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric",
      }),
      image: article.image || "/default-article.jpg",
      badgeColor: article.badgeColor || "#330df2",
      author: {
        name: article.author?.name || "Unknown Author",
        title: article.author?.title || "",
        avatar: article.author?.avatar || "/default-avatar.jpg",
        bio: article.author?.bio,
      },
      body: article.body || [],
      tags: (article.tags || []).map((tag: any) => ({
        name: tag.name,
        color: tag.badgeColor,
      })),
    };
  } catch (error) {
    console.error("Error fetching article:", error);
    return null;
  }
}

// Fetch all categories with article counts
export async function getCategories(): Promise<Category[]> {
  const query = `*[_type == "article"] {
    category
  }`;

  try {
    const articles = await client.fetch(query);

    // Count articles per category
    const categoryCounts = articles.reduce(
      (acc: Record<string, number>, article: any) => {
        acc[article.category] = (acc[article.category] || 0) + 1;
        return acc;
      },
      {}
    );

    // Get all unique categories
    const uniqueCategories = Array.from(
      new Set(articles.map((a: any) => a.category))
    ) as string[];

    // Transform to Category objects
    const categories: Category[] = [
      {
        id: "all",
        name: "All",
        count: articles.length,
        icon: "checklist_rtl",
      },
      ...uniqueCategories.map((category: string) => ({
        id: category.toLowerCase().replace(/\s+/g, "-"),
        name: category,
        count: categoryCounts[category] || 0,
        // Icon will be auto-matched in Navigation component
      })),
    ];

    return categories;
  } catch (error) {
    console.error("Error fetching categories:", error);
    return [];
  }
}

