                            placeholder="Enter your full name"
                            type="text"
                        />
                        {errors.fullName && (
                            <p className="text-red-400 text-sm mt-1">{errors.fullName.message}</p>
                        )}
                    </div>

                    <div className="flex flex-col">
                        <label className=" text-base font-medium leading-normal pb-2">
