'use client';

import { useEffect, useState } from 'react';
import type { MemeAssetType } from './types';

interface Props {
  onPlay: (video: MemeAssetType) => void;
  category?: string;
  sort?: string;
  search?: string;
}

export default function MemesLibraryGrid({ onPlay, category = 'all', sort = 'newest', search = '' }: Props) {
  const [items, setItems] = useState<MemeAssetType[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  useEffect(() => {
    async function load() {
      setLoading(true);
      try {
        const params = new URLSearchParams({
          category,
          sort,
          q: search,
          page: page.toString(),
          limit: '20',
        });
        const res = await fetch(`/api/memes?${params.toString()}`);
        const data = await res.json();
        setItems(data.items || []);
        setTotalPages(data.totalPages || 1);
      } catch (err) {
        console.error('Failed to load memes:', err);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [category, sort, search, page]);

  // Reset page when filters change
  useEffect(() => {
    setPage(1);
  }, [category, sort, search]);

  if (loading && page === 1) {
    return (
      <div className="flex-grow space-y-8">
        <div className="h-8 w-48 bg-slate-200 rounded animate-pulse" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="aspect-[16/10] bg-slate-100 rounded-3xl animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex-grow space-y-8">
      <h3 className="text-2xl font-bold font-headline">
        {category === 'all' ? 'Recently Added' : `${category} Memes`}
      </h3>

      {items.length === 0 ? (
        <div className="bg-surface-container-low rounded-3xl p-20 text-center border border-dashed border-slate-200">
          <span className="material-symbols-outlined text-5xl text-outline mb-4 block">sentiment_dissatisfied</span>
          <p className="font-bold text-on-surface-variant text-lg">No memes found</p>
          <p className="text-sm text-outline mt-1">Try adjusting your filters or search terms.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {items.map((v) => (
            <div
              key={v._id}
              className="group bg-surface-container-lowest rounded-3xl overflow-hidden shadow-sm hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 cursor-pointer"
              onClick={() => onPlay(v)}
            >
              <div className="relative aspect-[16/10]">
                {v.thumbnailUrl ? (
                  <img className="w-full h-full object-cover" alt={v.title} src={v.thumbnailUrl} />
                ) : (
                  <div className="w-full h-full bg-slate-200 flex items-center justify-center">
                    <span className="material-symbols-outlined text-5xl text-slate-400">videocam</span>
                  </div>
                )}
                <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/20">
                  <div className="w-16 h-16 bg-white/20 backdrop-blur-xl rounded-full flex items-center justify-center text-white scale-75 group-hover:scale-100 transition-transform">
                    <span className="material-symbols-outlined text-4xl" style={{ fontVariationSettings: "'FILL' 1" }}>play_arrow</span>
                  </div>
                </div>
                {v.duration && (
                  <span className="absolute bottom-3 right-3 px-2 py-1 rounded-lg bg-black/60 text-white text-[10px] font-bold backdrop-blur-sm">
                    {v.duration}
                  </span>
                )}
              </div>
              <div className="p-6">
                <div className="flex justify-between items-start mb-3">
                  <span className="text-[10px] font-extrabold uppercase tracking-widest text-primary px-2.5 py-1 rounded-md bg-primary/10">
                    {v.category}
                  </span>
                  <button
                    className="text-outline hover:text-primary transition-colors"
                    onClick={(e) => {
                      e.stopPropagation();
                      // Would call bookmark API here
                    }}
                  >
                    <span className="material-symbols-outlined">bookmark</span>
                  </button>
                </div>
                <h4 className="text-on-surface font-bold text-lg leading-tight mb-4 truncate">{v.title}</h4>
                <div className="flex items-center justify-between">
                  <a
                    href={`/api/download/${v._id}`}
                    className="flex items-center gap-2 px-4 py-2 bg-surface-container-low text-on-surface text-xs font-bold rounded-xl hover:bg-primary hover:text-white transition-all"
                    onClick={(e) => e.stopPropagation()}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <span className="material-symbols-outlined text-[18px]">download</span> Download
                  </a>
                  <span className="text-outline text-[11px] font-medium">{v.downloads || 0} Downloads</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-4 pt-8">
          <button
            onClick={() => setPage(p => Math.max(1, p - 1))}
            disabled={page === 1}
            className="px-4 py-2 bg-surface-container-low rounded-xl text-sm font-bold disabled:opacity-40 hover:bg-slate-200"
          >
            Prev
          </button>
          <span className="text-sm font-bold">Page {page} of {totalPages}</span>
          <button
            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
            className="px-4 py-2 bg-surface-container-low rounded-xl text-sm font-bold disabled:opacity-40 hover:bg-slate-200"
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import type { MemeAssetType } from './types';

interface Props {
  video: MemeAssetType;
  onClose: () => void;
  onPlay: (video: MemeAssetType) => void;
}

export default function MemesPlayModal({ video, onClose, onPlay }: Props) {
  const [related, setRelated] = useState<MemeAssetType[]>([]);
  const [showShare, setShowShare] = useState(false);

  // Fetch related videos (same category)
  useEffect(() => {
    async function loadRelated() {
      const res = await fetch(`/api/memes?category=${video.category}&limit=6`);
      const data = await res.json();
      setRelated((data.items || []).filter((v: MemeAssetType) => v._id !== video._id));
    }
    loadRelated();
    setShowShare(false);
  }, [video]);

  // Handle escape key
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [onClose]);

  const stats = [
    { label: 'Resolution', value: '1080p' }, // Placeholder
    { label: 'File Size',  value: `${(video.sizeBytes / (1024 * 1024)).toFixed(1)} MB` },
    { label: 'Format',     value: video.mimeType.split('/').pop()?.toUpperCase() || 'MP4' },
    { label: 'Downloads',  value: video.downloads?.toLocaleString() || '0' },
  ];

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-8 animate-in fade-in duration-300">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-on-surface/90 backdrop-blur-md cursor-pointer"
        onClick={onClose}
      />

      <div className="relative w-full max-w-7xl h-full max-h-[90vh] bg-surface-container-lowest rounded-[2.5rem] shadow-2xl overflow-hidden flex flex-col xl:flex-row animate-in slide-in-from-bottom-8 duration-500">
        {/* Close Button Mobile */}
        <button 
          onClick={onClose}
          className="xl:hidden absolute top-4 right-4 z-[110] w-10 h-10 rounded-full bg-black/40 text-white flex items-center justify-center backdrop-blur-md"
        >
          <span className="material-symbols-outlined">close</span>
        </button>

        {/* Left: Video Player Area */}
        <div className="flex-grow bg-black flex flex-col">
          <div className="flex-grow flex items-center justify-center relative group">
            <video 
              key={video.publicUrl}
              src={video.publicUrl}
              controls
              autoPlay
              className="max-w-full max-h-full"
            />
          </div>
          
          {/* Related strip (below player on desktop) */}
          <div className="h-32 bg-on-surface/20 backdrop-blur-xl p-4 flex gap-4 overflow-x-auto items-center">
            {related.map((v) => (
              <div 
                key={v._id}
                onClick={() => onPlay(v)}
                className="w-40 h-full flex-shrink-0 bg-surface-container-low rounded-xl overflow-hidden cursor-pointer hover:ring-2 hover:ring-primary transition-all relative group"
              >
                <img src={v.thumbnailUrl || v.publicUrl} alt={v.title} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                  <span className="material-symbols-outlined text-white text-xl">play_arrow</span>
                </div>
              </div>
            ))}
            {related.length === 0 && <p className="text-white/40 text-sm italic py-4">No related memes found</p>}
          </div>
        </div>

        {/* Right: Sidebar Info */}
        <div className="w-full xl:w-[400px] flex-shrink-0 bg-surface-container-lowest border-l border-slate-100 flex flex-col p-8 overflow-y-auto">
          <div className="flex justify-between items-start mb-6">
            <h2 className="text-2xl font-black font-headline text-on-surface pr-8 leading-tight">{video.title}</h2>
            <button 
              onClick={onClose}
              className="hidden xl:flex w-10 h-10 rounded-xl bg-surface-container-low text-on-surface-variant items-center justify-center hover:bg-slate-200 transition-colors"
            >
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>

          <div className="flex flex-wrap gap-2 mb-8">
            <span className="px-3 py-1 rounded-lg bg-primary/10 text-primary text-[10px] font-extrabold uppercase tracking-widest">{video.category}</span>
            {video.tags?.map(t => (
              <span key={t} className="px-3 py-1 rounded-lg bg-surface-container-low text-on-surface-variant text-[10px] font-bold">{t}</span>
            ))}
          </div>

          <div className="grid grid-cols-2 gap-4 mb-8">
            {stats.map(s => (
              <div key={s.label} className="p-4 rounded-2xl bg-surface-container-low/50 border border-slate-50">
                <p className="text-[10px] font-extrabold uppercase tracking-widest text-outline mb-1">{s.label}</p>
                <p className="text-sm font-black text-on-surface">{s.value}</p>
              </div>
            ))}
          </div>

          <div className="space-y-3 mb-8">
            <a 
              href={`/api/download/${video._id}`}
              target="_blank"
              rel="noopener noreferrer"
              className="w-full h-16 bg-primary text-on-primary rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all"
            >
              <span className="material-symbols-outlined text-2xl">download</span>
              FREE DOWNLOAD
            </a>
            <div className="flex gap-3">
              <button 
                className="flex-1 h-14 bg-surface-container-high rounded-2xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-surface-container-highest transition-all"
              >
                <span className="material-symbols-outlined text-xl">favorite</span>
                Save
              </button>
              <button 
                onClick={() => setShowShare(!showShare)}
                className="flex-1 h-14 bg-surface-container-high rounded-2xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-surface-container-highest transition-all"
              >
                <span className="material-symbols-outlined text-xl">share</span>
                Share
              </button>
            </div>
            {showShare && (
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex gap-4 animate-in slide-in-from-top-2">
                <button className="w-10 h-10 rounded-full bg-blue-500 text-white flex items-center justify-center"><i className="text-sm">X</i></button>
                <button className="w-10 h-10 rounded-full bg-green-500 text-white flex items-center justify-center"><i className="text-sm">W</i></button>
                <div className="flex-grow relative">
                  <input readOnly value={global?.location?.href} className="w-full h-10 bg-white border border-slate-200 rounded-lg text-[10px] px-3 pr-10 outline-none" />
                  <span className="material-symbols-outlined absolute right-2 top-1/2 -translate-y-1/2 text-sm text-slate-400 cursor-pointer">content_copy</span>
                </div>
              </div>
            )}
          </div>

          <div className="mt-auto">
            <div className="p-6 rounded-3xl bg-surface-container-low border-2 border-dashed border-primary/20">
              <h5 className="font-black text-primary text-xs uppercase tracking-widest mb-2">Usage License</h5>
              <p className="text-[11px] text-on-surface-variant leading-relaxed font-medium">
                This asset is free for commercial and non-commercial use. No attribution required, though appreciated. Redistribution as a library is prohibited.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import type { MemeAssetType } from './types';

interface Props { onPlay: (video: MemeAssetType) => void; }

export default function MemesTrending({ onPlay }: Props) {
  const [items, setItems] = useState<MemeAssetType[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const res = await fetch('/api/trending');
        const data = await res.json();
        setItems(data.items || []);
      } catch (err) {
        console.error('Failed to load trending memes:', err);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  if (loading) {
    return (
      <section className="animate-pulse">
        <div className="h-8 w-48 bg-slate-200 rounded mb-6" />
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="aspect-video bg-slate-100 rounded-2xl" />
          ))}
        </div>
      </section>
    );
  }

  if (items.length === 0) return null;

  return (
    <section>
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-2xl font-bold font-headline">Currently Trending</h3>
        <a className="text-primary font-bold text-sm flex items-center gap-1 hover:underline" href="#">
          View All <span className="material-symbols-outlined text-sm">arrow_forward</span>
        </a>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {items.map((meme) => (
          <div
            key={meme._id}
            className="group relative aspect-video rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 cursor-pointer"
            onClick={() => onPlay(meme)}
          >
            {/* Using 1st frame/thumbnail if available, otherwise a placeholder or video tag */}
            {meme.thumbnailUrl ? (
              <img
                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                alt={meme.title}
                src={meme.thumbnailUrl}
              />
            ) : (
              <div className="w-full h-full bg-slate-200 flex items-center justify-center">
                <span className="material-symbols-outlined text-4xl text-slate-400">videocam</span>
              </div>
            )}
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent flex flex-col justify-end p-5">
              <span className="absolute top-4 left-4 px-3 py-1 rounded-full bg-white/70 backdrop-blur-sm text-[10px] font-bold text-on-surface flex items-center gap-1">
                <span className="material-symbols-outlined text-[14px] text-error" style={{ fontVariationSettings: "'FILL' 1" }}>trending_up</span> TRENDING
              </span>
              <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                <div className="w-14 h-14 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center border border-white/40">
                  <span className="material-symbols-outlined text-white text-3xl" style={{ fontVariationSettings: "'FILL' 1" }}>play_arrow</span>
                </div>
              </div>
              <h4 className="text-white font-bold leading-tight truncate">{meme.title}</h4>
              <p className="text-white/60 text-xs mt-1">{meme.category} {meme.duration ? `ΓÇó ${meme.duration}` : ''}</p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

'use client'

import React, { useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import IconButton from './ui/IconButton'
import Button from '@/app/services/components/ui/Button'
import { PortfolioItem } from './types'

interface CaseStudyModalProps {
    item: PortfolioItem | null
    isOpen: boolean
    onClose: () => void
}

const CaseStudyModal: React.FC<CaseStudyModalProps> = ({ item, isOpen, onClose }) => {
    // Prevent scrolling when modal is open
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden'
        } else {
            document.body.style.overflow = 'unset'
        }
        return () => { document.body.style.overflow = 'unset' }
    }, [isOpen])

    return (
        <AnimatePresence>
            {isOpen && item && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6">
                    {/* 1. Enhanced Backdrop */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="absolute inset-0 bg-black/80 backdrop-blur-md"
                    />

                    {/* 2. Animated Modal Container */}
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        exit={{ opacity: 0, scale: 0.95, y: 20 }}
                        transition={{ type: 'spring', duration: 0.5, bounce: 0.3 }}
                        className="relative bg-background-dark border border-white/10 rounded-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col shadow-[0_0_50px_-12px_rgba(0,0,0,0.5)] ring-1 ring-white/5"
                        onClick={(e) => e.stopPropagation()}
                    >
                        {/* Modal Header - Sticky with better contrast */}
                        <div className="z-20 bg-background-dark/95 backdrop-blur-md border-b border-white/10 p-6">
                            <div className="flex justify-between items-start">
                                <div>
                                    <div className="flex items-center gap-3 mb-2">
                                        <span className="text-[10px] tracking-widest px-2 py-0.5 rounded bg-primary/10 text-primary font-bold border border-primary/20">
                                            {item.category.toUpperCase()}
                                        </span>
                                        <span className=" text-white text-sm font-mono">{item.year}</span>
                                    </div>
                                    <h2 className="text-2xl md:text-3xl font-bold text-white tracking-tight">{item.title}</h2>
                                    {item.client && (
                                        <p className="text-white text-sm mt-1">Project for: <span className="text-white/80">{item.client}</span></p>
                                    )}
                                </div>
                                <IconButton
                                    icon={<span className="material-symbols-outlined">close</span>}
